<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/analytics/BasicAudienceService.php';
function basic_check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$pdo=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$root=sys_get_temp_dir().'/basic-audience-'.bin2hex(random_bytes(8));mkdir($root);file_put_contents($root.'/index.html','<h1>Fixture</h1>');
try {
 $s=new BasicAudienceService($pdo,$root);basic_check(!$s->ready(),'disabled until additive activation');basic_check($s->report()['page_views']===null,'missing is not zero');$s->install();$s->install();basic_check($s->ready(),'idempotent activation');basic_check($pdo->query("SELECT COUNT(*) FROM sqlite_master WHERE name='el_basic_delivery_keys'")->fetchColumn()===1,'delivery de-duplication schema installs additively');
 $pdo->exec("CREATE TABLE destinations(id INTEGER,slug TEXT,publication_status TEXT);CREATE TABLE businesses(id INTEGER,public_id TEXT,destination_id INTEGER,publication_status TEXT,information_status TEXT DEFAULT 'DATOS_PUBLICOS',operation_status TEXT DEFAULT 'EN_OPERACION');CREATE TABLE el_coverage_places(slug TEXT,department_code TEXT);INSERT INTO destinations VALUES(1,'jerico','published'),(2,'draft','draft');INSERT INTO el_coverage_places VALUES('jerico','05'),('draft','05');INSERT INTO businesses(id,public_id,destination_id,publication_status) VALUES(1,'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee',1,'published')");
 $pdo->exec("CREATE TABLE business_translations(business_id INTEGER,locale TEXT);INSERT INTO business_translations VALUES(1,'es');CREATE TABLE business_subscriptions(id INTEGER,business_id INTEGER,plan_code TEXT,status TEXT,starts_at TEXT,ends_at TEXT);INSERT INTO business_subscriptions VALUES(1,1,'page_premium','active',NULL,NULL);CREATE TABLE subscription_plans(code TEXT,has_business_page INTEGER);INSERT INTO subscription_plans VALUES('page_premium',1),('free',0);CREATE TABLE subscription_plan_features(plan_code TEXT,feature_code TEXT,included INTEGER);INSERT INTO subscription_plan_features VALUES('page_premium','business_page',1),('page_premium','highlighted_card',1)");
 $pdo->exec("CREATE TABLE business_contacts(business_id INTEGER,channel TEXT,is_public INTEGER,contact_value TEXT);INSERT INTO business_contacts VALUES(1,'whatsapp',1,'public'),(1,'email',0,'private');INSERT INTO subscription_plan_features VALUES('page_premium','direct_contact',1)");
 basic_check($s->countPage('/','2026-10-16 04:20:00','US'),'aggregate country without visitor IDs');
 $countries=$pdo->query('SELECT * FROM el_basic_country_daily')->fetchAll(PDO::FETCH_ASSOC);basic_check(count($countries)===1&&$countries[0]['country_code']==='US','country counter stores country only');basic_check(array_keys($countries[0])===['page_day','scope_code','destination_slug','country_code','page_views'],'country schema contains no IP or identifier');$pdo->exec('DELETE FROM el_basic_page_daily;DELETE FROM el_basic_country_daily');
 basic_check($s->countContact('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','whatsapp','2026-10-16 04:20:00'),'public channel click counts without consent');
 basic_check(!$s->countContact('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','email','2026-10-16 04:20:00'),'private channel never measured');
 basic_check(!$s->countContact('/lugares/otro/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','whatsapp','2026-10-16 04:20:00'),'cross-place forged contact rejected');
 basic_check((int)$pdo->query("SELECT metric_count FROM el_basic_entity_daily WHERE entity_type='business' AND metric='contact_click'")->fetchColumn()===1,'contact persisted once per event, not multiplied by country');
 $today=(new DateTimeImmutable('now',new DateTimeZone('America/Bogota')))->format('Y-m-d');$q=$pdo->prepare('INSERT INTO el_basic_country_daily VALUES(?,?,?,?,?)');foreach([['CO','jerico','US',5],['05','jerico','US',5],['CO','jerico','CO',3],['05','jerico','CO',3],['CO','','ZZ',2]] as $r)$q->execute([$today,...$r]);
 $international=$s->interestReport();basic_check($international['foreign_views']===5&&$international['country_known_views']===8,'country totals do not double-count portal and department scopes; unknown excluded from foreign share');
 $local=$s->interestReport(7,'05','jerico');basic_check($local['foreign_views']===5&&count($local['countries'])===2,'country chart honors place and period scopes');$pdo->exec('DELETE FROM el_basic_country_daily');
 $time='2026-10-16 04:30:00'; // Still 15 October in Bogotá.
 basic_check($s->countPage('/',$time),'home count without identity or consent');basic_check($s->countPage('/',$time),'refresh adds a view');basic_check(!$s->countPage('/destinos/jerico/',$time),'legacy destination route redirects and never counts');basic_check($s->countPage('/pt-br/lugares/jerico/',$time),'published destination route counts in every public language');basic_check($s->countPage('/negocios/aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee/',$time),'published business');basic_check($s->countPage('/',$time,'CO','aabbccdd-eeff-0011-2233-445566778899'),'first delivery key counts');basic_check($s->countPage('/',$time,'CO','aabbccdd-eeff-0011-2233-445566778899'),'retry delivery key is acknowledged');basic_check((int)$pdo->query('SELECT COUNT(*) FROM el_basic_delivery_keys')->fetchColumn()===1,'delivery key has no associated visitor data');
 foreach(['/admin/index.html','/api/cobertura.php','/business/dashboard.html','/negocios/portal/','/?email=private@example.com','/../private/config.php','/inventado/','/destinos/draft/','/destinos/jerico/not-real/'] as $path)basic_check(!$s->countPage($path,$time),'reject private, unpublished, unknown or parameterized path');
 $stored=$pdo->query('SELECT * FROM el_basic_page_daily ORDER BY scope_code')->fetchAll(PDO::FETCH_ASSOC);basic_check(count($stored)===2,'only portal and department totals');basic_check((int)$stored[0]['page_views']===2&&(int)$stored[1]['page_views']===5,'scopes not double summed');basic_check($stored[0]['page_day']==='2026-10-15','Bogotá day');basic_check(array_keys($stored[0])===['page_day','scope_code','page_views'],'no identity or path columns');
 basic_check($s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','card_impression',$time),'visible paid card');
 basic_check($s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','profile_click',$time),'click to paid page');
 basic_check(!$s->countCard('/lugares/otro/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','card_impression',$time),'wrong destination rejected');
 basic_check((int)$pdo->query("SELECT metric_count FROM el_basic_entity_daily WHERE entity_type='business' AND metric='card_impression'")->fetchColumn()===1,'business impression persisted separately');
 basic_check((int)$pdo->query("SELECT metric_count FROM el_basic_entity_daily WHERE entity_type='destination' AND metric='page_view' AND placement='business_profile'")->fetchColumn()===1,'business page rolls up to destination without inflating portal');
 basic_check($s->entityReport('destination','jerico',30,'2026-10-16 18:00:00')['metrics']['page_views']===2,'destination includes every canonical language route and business pages once each');
 basic_check($s->entityReport('business','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee',30,'2026-10-16 18:00:00')['metrics']['profile_clicks']===1,'private report groups correct target only');
 $pdo->exec("UPDATE business_subscriptions SET ends_at='2000-01-01'");
 basic_check(!$s->countPage('/negocios/aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee/',$time),'expired page rejected');
 basic_check(!$s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','profile_click',$time),'expired profile click rejected');
 basic_check($s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','card_impression',$time),'free listing remains measurable');
 basic_check((int)$pdo->query("SELECT metric_count FROM el_basic_entity_daily WHERE entity_type='business' AND metric='card_impression' AND placement='directory'")->fetchColumn()===1,'expired plan never reported as featured');
 $pdo->exec("INSERT INTO subscription_plans VALUES('featured',0),('page',1);INSERT INTO subscription_plan_features VALUES('featured','highlighted_card',1),('page','business_page',1);UPDATE business_subscriptions SET plan_code='featured',ends_at=NULL");
 basic_check(!$s->countPage('/negocios/aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee/',$time),'featured tier alone does not buy a page');
 basic_check($s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','card_impression',$time),'featured tier impression');
 $pdo->exec("UPDATE business_subscriptions SET plan_code='page'");
 basic_check($s->countPage('/negocios/aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee/',$time),'standard paid page');
 basic_check($s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','card_impression',$time),'standard page tier uses ordinary directory placement');
 basic_check((int)$pdo->query("SELECT metric_count FROM el_basic_entity_daily WHERE entity_type='business' AND metric='card_impression' AND placement='featured'")->fetchColumn()===2,'features not inferred from page ownership');
 $pdo->exec("UPDATE business_subscriptions SET starts_at='2999-01-01'");basic_check(!$s->countPage('/negocios/aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee/',$time),'future entitlement rejected');
 $pdo->exec("UPDATE business_subscriptions SET starts_at=NULL,status='pending_payment'");basic_check(!$s->countPage('/negocios/aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee/',$time),'pending payment not active entitlement');
 $pdo->exec("UPDATE business_subscriptions SET status='active';UPDATE businesses SET operation_status='CERRADO_DEFINITIVO'");basic_check(!$s->countCard('/lugares/jerico/','aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee','card_impression',$time),'closed business cannot get public impressions');
 $pdo->exec("UPDATE el_basic_settings SET setting_value='2026-01-01 05:00:00' WHERE setting_key='started_at';DELETE FROM el_basic_page_daily;INSERT INTO el_basic_page_daily VALUES('2026-08-20','CO',10),('2026-10-01','CO',20),('2026-10-16','CO',100)");
 $r=$s->report(30,null,'2026-10-16 18:00:00');basic_check($r['page_views']===120,'live views include partial today');basic_check($r['comparison_current_views']===20&&$r['previous_views']===10&&$r['growth_percent']===100.0,'compare completed equal windows, excludes today');basic_check($r['comparison_period_end']==='2026-10-15','comparison ends yesterday');
 $pdo->exec("UPDATE el_basic_settings SET setting_value='2026-10-16 12:00:00' WHERE setting_key='started_at'");basic_check(!$s->report(30,null,'2026-10-16 18:00:00')['comparison_available'],'no invented history');
 basic_check(!str_contains(json_encode($stored),'jerico'),'no raw paths, business IDs or journeys stored');
 $pdo->exec("INSERT INTO el_basic_page_daily VALUES('2020-01-01','CO',7);INSERT INTO el_basic_country_daily VALUES('2020-01-01','CO','','US',7)");
 $before=(int)$pdo->query('SELECT SUM(page_views) FROM el_basic_page_daily')->fetchColumn();$s->purge();basic_check((int)$pdo->query('SELECT SUM(page_views) FROM el_basic_page_daily')->fetchColumn()===$before,'scheduled purge preserves old aggregates');
 basic_check($s->countPage('/','2026-10-16 19:00:00'),'new count with old history');basic_check((int)$pdo->query("SELECT page_views FROM el_basic_page_daily WHERE page_day='2020-01-01'")->fetchColumn()===7,'normal counting does not age-delete history');
 $all=$s->report('all',null,'2026-10-16 20:00:00');basic_check($all['page_views']===138&&$all['period_mode']==='all'&&$all['comparison_available']===false&&$all['previous_views']===null,'all includes old daily totals and disables prior-period comparison');basic_check($all['period_start']==='2020-01-01','all labels retained history from earliest date');
 basic_check($s->interestReport('all')['foreign_views']===7,'all includes old country aggregates');
 $s->install();basic_check($pdo->query("SELECT setting_value FROM el_basic_settings WHERE setting_key='retention_days'")->fetchColumn()==='0','installation metadata no longer advertises expiration');
 echo "Basic audience: OK — aggregate-only schema, refresh, scopes, private route boundaries, activation, Bogotá and full-period comparisons\n";
} finally {unlink($root.'/index.html');rmdir($root);}
